CREATE COLUMN TABLE "TEST_AP"."BAL2" ("PeriodID" INTEGER CS_INT NOT NULL , "DateFrom" LONGDATE CS_LONGDATE NOT NULL , "DateTo" LONGDATE CS_LONGDATE NOT NULL , "FiscalYear" INTEGER CS_INT, "CreateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("PeriodID")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "BAL2_SECONDARY" ON "TEST_AP"."BAL2" ( "DateFrom" ASC, "DateTo" ASC )